package ai

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/sashabaranov/go-openai"
	"github.com/stretchr/testify/require"

	"github.com/gravitational/teleport/lib/ai/model"
)

func TestChat_PromptTokens(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		messages []openai.ChatCompletionMessage
		want     int
	}{
		{
			name:     "empty",
			messages: []openai.ChatCompletionMessage{},
			want:     0,
		},
		{
			name: "only system message",
			messages: []openai.ChatCompletionMessage{
				{
					Role:    openai.ChatMessageRoleSystem,
					Content: "Hello",
				},
			},
			want: 697,
		},
		{
			name: "system and user messages",
			messages: []openai.ChatCompletionMessage{
				{
					Role:    openai.ChatMessageRoleSystem,
					Content: "Hello",
				},
				{
					Role:    openai.ChatMessageRoleUser,
					Content: "Hi LLM.",
				},
			},
			want: 705,
		},
		{
			name: "tokenize our prompt",
			messages: []openai.ChatCompletionMessage{
				{
					Role:    openai.ChatMessageRoleSystem,
					Content: model.PromptCharacter("Bob"),
				},
				{
					Role:    openai.ChatMessageRoleUser,
					Content: "Show me free disk space on localhost node.",
				},
			},
			want: 908,
		},
	}

	for _, tt := range tests {
		tt := tt
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			responses := []string{
				generateCommandResponse(),
			}
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Content-Type", "text/event-stream")

				require.GreaterOrEqual(t, len(responses), 1, "Unexpected request")
				dataBytes := responses[0]
				_, err := w.Write([]byte(dataBytes))
				require.NoError(t, err, "Write error")

				responses = responses[1:]
			}))

			t.Cleanup(server.Close)

			cfg := openai.DefaultConfig("secret-test-token")
			cfg.BaseURL = server.URL + "/v1"

			client := NewClientFromConfig(cfg)
			chat := client.NewChat(nil, "Bob")

			for _, message := range tt.messages {
				chat.Insert(message.Role, message.Content)
			}

			ctx := context.Background()
			message, err := chat.Complete(ctx, "", func(aa *model.AgentAction) {})
			require.NoError(t, err)
			msg, ok := message.(interface{ UsedTokens() *model.TokensUsed })
			require.True(t, ok)

			usedTokens := msg.UsedTokens().Completion + msg.UsedTokens().Prompt
			require.Equal(t, tt.want, usedTokens)
		})
	}
}

func TestChat_Complete(t *testing.T) {
	t.Parallel()

	responses := [][]byte{
		[]byte(generateTextResponse()),
		[]byte(generateCommandResponse()),
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")

		require.GreaterOrEqual(t, len(responses), 1, "Unexpected request")
		dataBytes := responses[0]

		_, err := w.Write(dataBytes)
		require.NoError(t, err, "Write error")

		responses = responses[1:]
	}))
	defer server.Close()

	cfg := openai.DefaultConfig("secret-test-token")
	cfg.BaseURL = server.URL + "/v1"
	client := NewClientFromConfig(cfg)

	chat := client.NewChat(nil, "Bob")

	ctx := context.Background()
	_, err := chat.Complete(ctx, "Hello", func(aa *model.AgentAction) {})
	require.NoError(t, err)

	chat.Insert(openai.ChatMessageRoleUser, "Show me free disk space on localhost node.")

	t.Run("text completion", func(t *testing.T) {
		msg, err := chat.Complete(ctx, "Show me free disk space", func(aa *model.AgentAction) {})
		require.NoError(t, err)

		require.IsType(t, &model.StreamingMessage{}, msg)
		streamingMessage := msg.(*model.StreamingMessage)
		require.Equal(t, "Which ", <-streamingMessage.Parts)
		require.Equal(t, "node do ", <-streamingMessage.Parts)
		require.Equal(t, "you want ", <-streamingMessage.Parts)
		require.Equal(t, "use?", <-streamingMessage.Parts)
	})

	t.Run("command completion", func(t *testing.T) {
		msg, err := chat.Complete(ctx, "localhost", func(aa *model.AgentAction) {})
		require.NoError(t, err)

		require.IsType(t, &model.CompletionCommand{}, msg)
		command := msg.(*model.CompletionCommand)
		require.Equal(t, "df -h", command.Command)
		require.Len(t, command.Nodes, 1)
		require.Equal(t, "localhost", command.Nodes[0])
	})
}

// generateTextResponse generates a response for a text completion
func generateTextResponse() string {
	dataBytes := []byte{}
	dataBytes = append(dataBytes, []byte("event: message\n")...)

	data := `{"id":"1","object":"completion","created":1598069254,"model":"gpt-4","choices":[{"index": 0, "delta":{"content": "<FINAL RESPONSE>Which ", "role": "assistant"}}]}`
	dataBytes = append(dataBytes, []byte("data: "+data+"\n\n")...)
	dataBytes = append(dataBytes, []byte("event: message\n")...)

	data = `{"id":"2","object":"completion","created":1598069254,"model":"gpt-4","choices":[{"index": 0, "delta":{"content": "node do ", "role": "assistant"}}]}`
	dataBytes = append(dataBytes, []byte("data: "+data+"\n\n")...)
	dataBytes = append(dataBytes, []byte("event: message\n")...)

	data = `{"id":"3","object":"completion","created":1598069255,"model":"gpt-4","choices":[{"index": 0, "delta":{"content": "you want ", "role": "assistant"}}]}`
	dataBytes = append(dataBytes, []byte("data: "+data+"\n\n")...)
	dataBytes = append(dataBytes, []byte("event: message\n")...)

	data = `{"id":"4","object":"completion","created":1598069254,"model":"gpt-4","choices":[{"index": 0, "delta":{"content": "use?", "role": "assistant"}}]}`
	dataBytes = append(dataBytes, []byte("data: "+data+"\n\n")...)
	dataBytes = append(dataBytes, []byte("event: done\n")...)

	dataBytes = append(dataBytes, []byte("data: [DONE]\n\n")...)

	return string(dataBytes)
}

// generateCommandResponse generates a response for the command "df -h" on the node "localhost"
func generateCommandResponse() string {
	dataBytes := []byte{}
	dataBytes = append(dataBytes, []byte("event: message\n")...)

	actionObj := model.PlanOutput{
		Action: "Command Execution",
		ActionInput: struct {
			Command string   `json:"command"`
			Nodes   []string `json:"nodes"`
		}{"df -h", []string{"localhost"}},
	}
	actionJson, err := json.Marshal(actionObj)
	if err != nil {
		panic(err)
	}

	obj := struct {
		Content string `json:"content"`
		Role    string `json:"role"`
	}{
		Content: string(actionJson),
		Role:    "assistant",
	}
	json, err := json.Marshal(obj)
	if err != nil {
		panic(err)
	}

	data := fmt.Sprintf(`{"id":"1","object":"completion","created":1598069254,"model":"gpt-4","choices":[{"index": 0, "delta":%v}]}`, string(json))
	dataBytes = append(dataBytes, []byte("data: "+data+"\n\n")...)

	dataBytes = append(dataBytes, []byte("event: done\n")...)
	dataBytes = append(dataBytes, []byte("data: [DONE]\n\n")...)

	return string(dataBytes)
}

func (a *Agent) plan(ctx context.Context, state *executionState) (*AgentAction, *agentFinish, error) {
	scratchpad := a.constructScratchpad(state.intermediateSteps, state.observations)
	prompt := a.createPrompt(state.chatHistory, scratchpad, state.humanMessage)
	stream, err := state.llm.CreateChatCompletionStream(
		ctx,
		openai.ChatCompletionRequest{
			Model:       openai.GPT4,
			Messages:    prompt,
			Temperature: 0.3,
			Stream:      true,
		},
	)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	deltas := make(chan string)
	completion := strings.Builder{}
	go func() {
		defer close(deltas)

		for {
			response, err := stream.Recv()
			if errors.Is(err, io.EOF) {
				return
			} else if err != nil {
				log.Tracef("agent encountered an error while streaming: %v", err)
				return
			}

			delta := response.Choices[0].Delta.Content
			deltas <- delta
			// TODO(jakule): Fix token counting. Uncommenting the line below causes a race condition.
			//completion.WriteString(delta)
		}
	}()

	action, finish, err := parsePlanningOutput(deltas)
	state.tokensUsed.AddTokens(prompt, completion.String())
	return action, finish, trace.Wrap(err)
}

func (a *Agent) createPrompt(chatHistory, agentScratchpad []openai.ChatCompletionMessage, humanMessage openai.ChatCompletionMessage) []openai.ChatCompletionMessage {
	prompt := make([]openai.ChatCompletionMessage, 0)
	prompt = append(prompt, chatHistory...)
	toolList := strings.Builder{}
	toolNames := make([]string, 0, len(a.tools))
	for _, tool := range a.tools {
		toolNames = append(toolNames, tool.Name())
		toolList.WriteString("> ")
		toolList.WriteString(tool.Name())
		toolList.WriteString(": ")
		toolList.WriteString(tool.Description())
		toolList.WriteString("\n")
	}

	if len(a.tools) == 0 {
		toolList.WriteString("No tools available.")
	}

	formatInstructions := conversationParserFormatInstructionsPrompt(toolNames)
	newHumanMessage := conversationToolUsePrompt(toolList.String(), formatInstructions, humanMessage.Content)
	prompt = append(prompt, openai.ChatCompletionMessage{
		Role:    openai.ChatMessageRoleUser,
		Content: newHumanMessage,
	})

	prompt = append(prompt, agentScratchpad...)
	return prompt
}

func (a *Agent) constructScratchpad(intermediateSteps []AgentAction, observations []string) []openai.ChatCompletionMessage {
	var thoughts []openai.ChatCompletionMessage
	for i, action := range intermediateSteps {
		thoughts = append(thoughts, openai.ChatCompletionMessage{
			Role:    openai.ChatMessageRoleAssistant,
			Content: action.Log,
		}, openai.ChatCompletionMessage{
			Role:    openai.ChatMessageRoleUser,
			Content: conversationToolResponse(observations[i]),
		})
	}

	return thoughts
}

// parseJSONFromModel parses a JSON object from the model output and attempts to sanitize contaminant text
// to avoid triggering self-correction due to some natural language being bundled with the JSON.
// The output type is generic, and thus the structure of the expected JSON varies depending on T.
func parseJSONFromModel[T any](text string) (T, *invalidOutputError) {
	cleaned := strings.TrimSpace(text)
	if strings.Contains(cleaned, "```json") {
		cleaned = strings.Split(cleaned, "```json")[1]
	}
	if strings.Contains(cleaned, "```") {
		cleaned = strings.Split(cleaned, "```")[0]
	}
	cleaned = strings.TrimPrefix(cleaned, "```json")
	cleaned = strings.TrimPrefix(cleaned, "```")
	cleaned = strings.TrimSuffix(cleaned, "```")
	cleaned = strings.TrimSpace(cleaned)
	var output T
	err := json.Unmarshal([]byte(cleaned), &output)
	if err != nil {
		return output, newInvalidOutputErrorWithParseError(err)
	}

	return output, nil
}

// PlanOutput describes the expected JSON output after asking it to plan its next action.
type PlanOutput struct {
	Action      string `json:"action"`
	ActionInput any    `json:"action_input"`
	Reasoning   string `json:"reasoning"`
}

// parsePlanningOutput parses the output of the model after asking it to plan its next action
// and returns the appropriate event type or an error.
func parsePlanningOutput(deltas <-chan string) (*AgentAction, *agentFinish, error) {
	var text string
	for delta := range deltas {
		text += delta

		if strings.HasPrefix(text, finalResponseHeader) {
			parts := make(chan string)
			go func() {
				defer close(parts)

				parts <- strings.TrimPrefix(text, finalResponseHeader)
				for delta := range deltas {
					parts <- delta
				}
			}()

			return nil, &agentFinish{output: &StreamingMessage{Parts: parts, TokensUsed: newTokensUsed_Cl100kBase()}}, nil
		}
	}

	log.Tracef("received planning output: \"%v\"", text)
	if outputString, found := strings.CutPrefix(text, finalResponseHeader); found {
		return nil, &agentFinish{output: &Message{Content: outputString, TokensUsed: newTokensUsed_Cl100kBase()}}, nil
	}

	response, err := parseJSONFromModel[PlanOutput](text)
	if err != nil {
		log.WithError(err).Trace("failed to parse planning output")
		return nil, nil, trace.Wrap(err)
	}

	if v, ok := response.ActionInput.(string); ok {
		return &AgentAction{Action: response.Action, Input: v}, nil, nil
	} else {
		input, err := json.Marshal(response.ActionInput)
		if err != nil {
			return nil, nil, trace.Wrap(err)
		}

		return &AgentAction{Action: response.Action, Input: string(input), Reasoning: response.Reasoning}, nil, nil
	}
}
